O("n11809234008", "פרידה", "Farewell (Vaarwel)", 52.387654, 4.882422, "פסל", ["h3"],
  "פסל ברונזה של גודליבה סמולדרס בשם 'פרידה', ליד המים של הנמל המערבי הישן, בצד המערבי של העיר. השם מעורר את רגעי הפרידה על הרציפים, מקום שממנו יצאו ספינות ובו נשארו מי שליוו אותן.",
  "כ-310 מטרים בקו אווירי מהאיים המערביים ומווסטרדוק, באזור הגדה הדרומית של האיי.",
  "גודליבה סמולדרס היא אמנית הולנדית. לפי OSM 'פרידה' עשוי ברונזה. ב-OSM אין תיאור של הדמויות ואין שנת הצבה, ולכן הם אינם מובאים כאן. הפסל עומד בצד הדרומי של האיי, סמוך לאיים המערביים ולנמל המערבי הישן, שממנו יצאו בעבר ספינות לדרכים ארוכות.",
  "",
  ["לפי OSM הפסל עשוי ברונזה."],
  "משלבים עם טיול באיים המערביים ובווסטרדוק.", w=0, yr="", by="גודליבה סמולדרס"),

O("n11092205488", "האישה עם הדגים", "Fish Woman (Visvrouw)", 52.391146, 4.942806, "פסל", ["ani", "h3"],
  "פסל ברונזה של קרין בק בשם 'אשת הדגים', ככל הנראה דמות של מוכרת דגים, אחת הדמויות המוכרות של השווקים ההולנדיים. הוא עומד ליד כפר הגן נייוונדאם, ויש לו ערך בוויקיפדיה ההולנדית.",
  "בנורד, כ-880 מטרים בקו אווירי מהנייוונדאמרדייק ומכפרי הגן של נורד, סמוך לרקדנית עם הטמבורין ולפסלי הילדו קרופ.",
  "קרין בק היא פסלת הולנדית. לפי OSM 'אשת הדגים' עשוי ברונזה, ולפי ויקידאטה הוא פסל של קרין בק באמסטרדם. ב-OSM אין שנת הצבה. מוכרות הדגים בשווקים ובדוכנים היו חלק מחיי הערים ההולנדיות במשך מאות שנים, ובנייוונדאם, כפר שתושביו התפרנסו מהדיג, יש לנושא הד מקומי.",
  "ליצירה יש ערך בוויקיפדיה ההולנדית ופריט בוויקידאטה.",
  ["לפי OSM הפסל עשוי ברונזה."],
  "משלבים עם הרקדנית, עם נגר הספינות ועם שני הפסלים של הילדו קרופ, כולם במרחק הליכה קצר.", w=1, yr="", by="קרין בק",
  kids="אישה שמוכרת דגים בשוק. בהולנד אוהבים לאכול הרינג, דג קטן ומלוח. הייתם מעזים לטעום?"),

O("n11962331267", "החיפושית קרנן הצבי", "Stag Beetle (Vliegend Hert)", 52.392182, 4.9573, "פסל", ["ani"],
  "פסל מ-2002 של תאו סחפנס בשם 'Vliegend Hert', מילולית 'צבי מעופף', שהוא בהולנדית שמה של חיפושית קרנן הצבי, החיפושית הגדולה עם הלסתות שנראות כמו קרני צבי.",
  "בנורד, באזור נייוונדאם, כ-1.9 קילומטרים בקו אווירי מהנייוונדאמרדייק ומכפרי הגן של נורד. כדאי לנווט לפי הנקודה שבמפה.",
  "חיפושית קרנן הצבי היא מהחרקים הגדולים באירופה. לזכרים יש לסתות ענקיות שמזכירות קרני צבי, ובהן הם נאבקים זה בזה. בהולנד היא נדירה. לפי OSM הפסל הוצב ב-2002 ויצר אותו תאו סחפנס. ב-OSM אין פרטים על החומר ואין תיאור, ולכן לא ידוע מהנתונים אם הפסל מציג את החיפושית עצמה או משחק בשם.",
  "",
  ["לפי OSM הפסל הוצב ב-2002.", "Vliegend Hert הוא בהולנדית שמה של חיפושית קרנן הצבי."],
  "מתאים לעצירה בסיבוב אופניים במזרח נורד.", w=0, yr="2002", by="תאו סחפנס",
  kids="בהולנדית קוראים לחיפושית הזו 'צבי מעופף', כי יש לה קרניים כמו לצבי והיא יודעת לעוף. אפשר לבדוק: הפסל נראה יותר כמו חיפושית או כמו צבי?"),

